-- Rifts World Book 19: Australia - its bestiary and its notable NPCs.
-- 14 creatures (migration 074) and 4 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-australia-bestiary.sql
--
-- Written by scripts/bestiary-sql.mjs from 3 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.





-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 14 creatures are in' AS assertion, count(*) AS got, 14 AS want
  FROM creatures WHERE slug IN ('bunyip', 'devil-dingo', 'mopaditis', 'garkain', 'yara-mayha-sho', 'wandjinas', 'yowie', 'demon-frog', 'desert-worm', 'giant-cockroach', 'giant-dwombat', 'giant-kang', 'razorback', 'sand-fiend');
SELECT 'and 0 of them are playable' AS assertion, count(*) AS got, 0 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('bunyip', 'devil-dingo', 'mopaditis', 'garkain', 'yara-mayha-sho', 'wandjinas', 'yowie', 'demon-frog', 'desert-worm', 'giant-cockroach', 'giant-dwombat', 'giant-kang', 'razorback', 'sand-fiend');
SELECT 'all 4 notable NPCs are in' AS assertion, count(*) AS got, 4 AS want
  FROM notable_npcs WHERE slug IN ('mister-money', 'danny-winters', 'kay-mac-2', 'rainbow-serpent-avatar');
SELECT 'the creatures carry 62 attacks' AS assertion, count(*) AS got, 62 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('bunyip', 'devil-dingo', 'mopaditis', 'garkain', 'yara-mayha-sho', 'wandjinas', 'yowie', 'demon-frog', 'desert-worm', 'giant-cockroach', 'giant-dwombat', 'giant-kang', 'razorback', 'sand-fiend');
SELECT 'and the notables 6' AS assertion, count(*) AS got, 6 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('mister-money', 'danny-winters', 'kay-mac-2', 'rainbow-serpent-avatar');

