INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('creature', 'giant-kang', 'Leap Kick', '6D6 M.D.', 1, NULL, 'Anything weighing less than two tons is knocked off its feet and either sent flying 2D4x10 yards/meters or stomped into the ground; either way the victim takes an additional 1D4 M.D. and loses initiative and two melee attacks/actions. Needs a running leap of at least 20 yards/meters. Counts as two melee attacks.', 6),
('creature', 'razorback', 'Head Butt', 'Punch damage from supernatural P.S.', 1, NULL, NULL, 0),
('creature', 'razorback', 'Bite or Swipe with Tusk', '1D6 M.D.', 1, NULL, NULL, 1),
('creature', 'razorback', 'Stab and Rip with Tusks', '3D6 M.D.', 1, NULL, NULL, 2),
('creature', 'razorback', 'Stomp/Kick with front legs', 'Punch damage from supernatural P.S.', 1, NULL, NULL, 3),
('creature', 'razorback', 'Rear Leg Kick', 'Punch damage from supernatural P.S. +1D6', 1, NULL, NULL, 4),
('creature', 'razorback', 'Blade Swipe', '1D6 M.D.', 1, NULL, NULL, 5),
('creature', 'razorback', 'Blade Charge/Ram', '5D6 M.D.', 1, NULL, 'Counts as three melee attacks and may only be performed once per melee round.', 6),
('creature', 'razorback', 'Berserker Attack', '1D6x10 M.D.', 1, NULL, 'Uses up all melee attacks. Also either pins the opponent (loses one attack) or knocks him down (loses initiative and two melee attacks/actions). Avoided only by a dodge, or a parry that knocks the beast away with a shield or spear.', 7),
